import{_ as i,o as a,c as t,a2 as l}from"./chunks/framework.CTeY_0bQ.js";const u=JSON.parse('{"title":"0006 确定性引擎 + 平台能力层：先手写，后生成","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"reference/adr/0006-deterministic-engine-platform-capabilities.md","filePath":"reference/adr/0006-deterministic-engine-platform-capabilities.md","lastUpdated":null}'),o={name:"reference/adr/0006-deterministic-engine-platform-capabilities.md"};function r(n,e,s,d,c,h){return a(),t("div",null,[...e[0]||(e[0]=[l('<div><h1 id="_0006-确定性引擎-平台能力层-先手写-后生成" tabindex="-1">0006 确定性引擎 + 平台能力层：先手写，后生成 <a class="header-anchor" href="#_0006-确定性引擎-平台能力层-先手写-后生成" aria-label="Permalink to &quot;0006 确定性引擎 + 平台能力层：先手写，后生成&quot;">​</a></h1><ul><li>状态：提议（项目负责人已同意方向，待摸底实验结果确认）</li><li>日期：2026-10-25</li><li>关联：<a href="./0001-new-repo-core-and-adapters">ADR 0001</a>、<a href="./0002-two-orchestration-modes">ADR 0002</a>、<a href="./0003-generate-once-then-lock">ADR 0003</a></li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>AI loop 摸高项目要在公司自建的 agent 平台上做第一个试用，同时项目目标是通用适配，不绑定单个平台。已确认：摸高平台与&quot;有命令行、能启动任务、恢复和取消 HITL&quot;的内部平台是同一个平台。</p><p>平台提供 JS 动态工作流，也允许在主会话里手动发起子 agent。</p><h2 id="决定" tabindex="-1">决定 <a class="header-anchor" href="#决定" aria-label="Permalink to &quot;决定&quot;">​</a></h2><ol><li><strong>不使用平台自带的动态工作流</strong>。它和 laoshi 的引擎编排重叠，会让流程规则出现两份。</li><li><strong>最终形态是确定性步骤编排（引擎），不是 AI 在会话里编排</strong>。顺序、重试、超时、关卡由引擎决定；AI 只在步骤内工作。模式 B（会话内编排，见 ADR 0002）仍是有条件的备选，不进主路径。</li><li><strong>引擎统一提供；依赖平台的能力在目标平台上探测后补充实现</strong>。实现形式不限（命令行调用、脚本、少量代码），验收标准是契约一致性测试和探针通过，而不是实现形式。</li><li><strong>步骤 agent 优先用平台命令行起任务</strong>；主会话子 agent 只作为可选能力，不进主路径。</li><li><strong>先手写、后生成</strong>： <ol><li>第一个内部平台适配器由人依据摸底结果手写；</li><li>探针与一致性测试（<code>runConformance</code>）先于任何生成；</li><li>手里有至少两个手写适配器（Paseo、内部平台）作样本和真值后，再让 LLM 起草适配器，经人审阅后锁定（ADR 0003），并用已知平台反向验证它能复现手写版本。</li></ol></li></ol><h2 id="理由" tabindex="-1">理由 <a class="header-anchor" href="#理由" aria-label="Permalink to &quot;理由&quot;">​</a></h2><ul><li>确定性骨架加步骤内 AI 是业界成熟做法（Anthropic 的 workflow 与 agent 区分；Archon 等）。</li><li>多 agent 适配在业界都是人手写适配器（ACP、agentapi），没有找到&quot;LLM 自行生成并锁定平台适配器&quot;的公开先例；论文里 OpenAPI 到 MCP 的自动生成也要靠规范修复和测试把关。</li><li>通用性的证据来自契约、一致性测试和两个以上适配器，不依赖自动生成。</li></ul><h2 id="前置事实-摸底实验-1-3-回答" tabindex="-1">前置事实（摸底实验 1~3 回答） <a class="header-anchor" href="#前置事实-摸底实验-1-3-回答" aria-label="Permalink to &quot;前置事实（摸底实验 1~3 回答）&quot;">​</a></h2><ol><li>引擎进程能在哪里运行：沙箱里是否有 Node、能否安装依赖、后台进程能存活多久、能否调用平台命令行。</li><li>命令行能否起任务并查询状态，状态取值有哪些。</li><li>HITL 的真实语义（回合之间还是中途提问；取消请求后任务如何）。</li></ol><p>三项里任何一项答案为&quot;否&quot;，需回到本 ADR 重新评估引擎的位置与 <code>wait</code> 的实现方式。</p><h2 id="影响" tabindex="-1">影响 <a class="header-anchor" href="#影响" aria-label="Permalink to &quot;影响&quot;">​</a></h2><ul><li>计划中内部平台适配器（M4）优先级提高，与无头 CLI 运行时（M3）并行；初始化与生成（M5）排在两个手写适配器之后。</li><li>平台摸底清单从&quot;了解平台&quot;升级为&quot;决定引擎放哪、<code>wait</code> 怎么实现、HITL 怎么映射&quot;的依据。</li><li>不改变对外契约（ADR 0004）。</li></ul></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/laoshi/blob/main/docs/adr/0006-deterministic-engine-platform-capabilities.md">docs/adr/0006-deterministic-engine-platform-capabilities.md</a> 生成。<a href="https://github.com/yiyisf/laoshi/edit/main/docs/adr/0006-deterministic-engine-platform-capabilities.md">在 GitHub 上编辑</a></p>',2)])])}const m=i(o,[["render",r]]);export{u as __pageData,m as default};
